from full_surface import FullSurface
import numpy as np,json,torch
from pathlib import Path
from scipy.spatial import cKDTree
torch.set_num_threads(1);s=FullSurface();x=s.mesh['x'];faces=s.mesh['cut_minus'];tri=x[faces];A=np.eye(3);ab=(A[0]+A[1])/2;ac=(A[0]+A[2])/2;bc=(A[1]+A[2])/2;subs=np.array([[A[0],ab,ac],[ab,A[1],bc],[ac,bc,A[2]],[ab,bc,ac]]);base=np.array([[2/3,1/6,1/6],[1/6,2/3,1/6],[1/6,1/6,2/3]]);bary=np.einsum('qi,tij->tqj',base,subs).reshape(-1,3);points=np.einsum('qi,tij->tqj',bary,tri).reshape(-1,3);area=np.linalg.norm(np.cross(tri[:,1]-tri[:,0],tri[:,2]-tri[:,0]),axis=1)/2;raw=np.repeat(area/12,12);centers=np.array([np.average(s.mapping['source_pair_coordinates'][p['pair_indices']],axis=0,weights=p['weights']) for p in s.registry['patches']]);group=cKDTree(centers).query(points)[1];weights=raw/np.bincount(group,weights=raw,minlength=47)[group]
np.savez_compressed(Path(__file__).with_name('quadrature_refined.npz'),faces=np.repeat(faces,12,axis=0),barycentric=np.tile(bary,(len(faces),1)),points=points,groups=group,weights=weights)
r=FullSurface(quadrature='quadrature_refined.npz');plus=np.unique(s.mesh['tets'][s.mesh['tet_side']>0]);q=x.copy();q[plus,0]+=.0002*(1+.3*np.sin(80*x[plus,1]));q[plus,1]+=.00005*(1+.2*np.cos(100*x[plus,2]));a=s.evaluate(q);b=r.evaluate(q);fe=np.linalg.norm(a['force']-b['force'])/np.linalg.norm(b['force']);ee=abs(a['stored_energy_j']-b['stored_energy_j'])/b['stored_energy_j'];out=dict(scope='Prescribed nonuniform smooth opening, 3 versus 12 quadrature points per triangle; not a dynamic refinement',coarse_points=len(s.quad['points']),fine_points=len(points),force_relative_error=float(fe),energy_relative_error=float(ee),passed=bool(fe<=.05 and ee<=.05));Path(__file__).with_name('quadrature_refinement_result.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
